import java.awt.*;
import java.awt.event.*;
import java.net.URI;
import java.util.*;
import java.util.List;
import javax.swing.*;
import javax.swing.border.*;
import javax.swing.plaf.basic.BasicTabbedPaneUI;
import javax.swing.table.*;

final class VulnShell extends JPanel {
    final VulnApp app;
    final Map<String,JButton> navigation=new LinkedHashMap<>();
    final JLabel currentTool=VulnTheme.label("Overview",16,VulnTheme.TEXT),proxyState=VulnTheme.label("Proxy stopped",12,VulnTheme.MUTED),tlsState=VulnTheme.label("TLS tunnel",12,VulnTheme.MUTED),messageCount=VulnTheme.label("0 messages",12,VulnTheme.MUTED);
    final Overview overview;
    final javax.swing.Timer timer;
    static final Map<String,String> TITLES=Map.of("Dashboard","Overview","Target","Targets","Logger","Event log","TLS","TLS & certificates","Extensions","Extensions");
    VulnShell(VulnApp app){super(new BorderLayout());this.app=app;setBackground(VulnTheme.CANVAS);
        JPanel side=new JPanel();side.setLayout(new BoxLayout(side,BoxLayout.Y_AXIS));side.setBackground(VulnTheme.NAV);side.setBorder(new CompoundBorder(new MatteBorder(0,0,0,1,VulnTheme.BORDER),new EmptyBorder(14,10,12,10)));side.setPreferredSize(new Dimension(258,600));
        JPanel brand=new JPanel(new FlowLayout(FlowLayout.LEFT,10,0));brand.setOpaque(false);brand.add(new JLabel(new ImageIcon(VulnTheme.icon(24))));brand.add(VulnTheme.label("VULN",17,VulnTheme.TEXT));brand.setMaximumSize(new Dimension(232,32));side.add(brand);side.add(Box.createVerticalStrut(7));JLabel tagline=VulnTheme.label("LOCAL WORKSPACE",9,VulnTheme.MUTED);tagline.setBorder(new EmptyBorder(0,8,0,0));side.add(tagline);side.add(Box.createVerticalStrut(14));
        group(side,"WORKSPACE",new String[]{"Dashboard","Target","Proxy","Logger","Organizer"});group(side,"TESTING",new String[]{"Repeater","Intruder","Scanner","WebSockets","Browser"});group(side,"ANALYSIS",new String[]{"Decoder","Codec pipeline","Sequencer","Comparer","Scan checks"});group(side,"SYSTEM",new String[]{"Scope","Rules","Sessions","TLS","Callbacks","Scripts","Extensions","Settings"});side.add(Box.createVerticalGlue());JLabel local=VulnTheme.label("●  Local workspace",11,VulnTheme.ACCENT);local.setBorder(new EmptyBorder(16,8,0,0));side.add(local);for(Component child:side.getComponents())if(child instanceof JComponent component)component.setAlignmentX(Component.LEFT_ALIGNMENT);JScrollPane nav=new JScrollPane(side,JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED,JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);nav.setBorder(null);nav.setPreferredSize(new Dimension(258,600));nav.getVerticalScrollBar().setUnitIncrement(20);add(nav,BorderLayout.WEST);
        JPanel body=new JPanel(new BorderLayout());body.setBackground(VulnTheme.CANVAS);JPanel top=new JPanel(new BorderLayout());top.setBorder(new CompoundBorder(new MatteBorder(0,0,1,0,VulnTheme.BORDER),new EmptyBorder(12,20,12,20)));JPanel crumbs=new JPanel(new FlowLayout(FlowLayout.LEFT,10,0));crumbs.setOpaque(false);crumbs.add(VulnTheme.label("My Workspace   /",12,VulnTheme.MUTED));crumbs.add(currentTool);top.add(crumbs);JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT,8,0));actions.setOpaque(false);actions.add(VulnApp.button("Wiki · PT-BR  F1",app::showWiki));actions.add(VulnApp.button("Switch tool  Ctrl K",this::palette));actions.add(VulnApp.button("Open project",app.advanced::openProject));actions.add(VulnApp.button("Save project",app.advanced::saveProject));top.add(actions,BorderLayout.EAST);body.add(top,BorderLayout.NORTH);
        overview=new Overview();app.tools.setComponentAt(0,overview);app.tools.setUI(new BasicTabbedPaneUI(){protected int calculateTabAreaHeight(int placement,int runCount,int maxTabHeight){return 0;}protected void paintTabArea(Graphics g,int placement,int selected){}protected Insets getContentBorderInsets(int placement){return new Insets(0,0,0,0);}});body.add(app.tools);
        JPanel footer=new JPanel(new BorderLayout());footer.setBorder(new CompoundBorder(new MatteBorder(1,0,0,0,VulnTheme.BORDER),new EmptyBorder(7,20,7,20)));app.status.setFont(new Font("Segoe UI",Font.PLAIN,11));app.status.setForeground(VulnTheme.MUTED);footer.add(app.status);JPanel state=new JPanel(new FlowLayout(FlowLayout.RIGHT,16,0));state.setOpaque(false);state.add(proxyState);state.add(tlsState);state.add(messageCount);footer.add(state,BorderLayout.EAST);body.add(footer,BorderLayout.SOUTH);add(body);
        app.tools.addChangeListener(e->updateSelection());updateSelection();bindings();timer=new javax.swing.Timer(700,e->refresh());timer.start();app.addWindowListener(new WindowAdapter(){public void windowClosed(WindowEvent e){timer.stop();}});refresh();
    }
    void group(JPanel side,String label,String[] names){JLabel title=VulnTheme.label(label,10,VulnTheme.MUTED);title.setBorder(new EmptyBorder(12,10,8,0));side.add(title);for(String name:names){JButton b=new JButton("    "+TITLES.getOrDefault(name,name));b.setHorizontalAlignment(SwingConstants.LEFT);b.setFont(new Font("Segoe UI",Font.PLAIN,13));b.setBorder(new EmptyBorder(9,16,9,12));b.setFocusPainted(true);b.putClientProperty("JButton.buttonType","square");b.setMaximumSize(new Dimension(234,36));b.setAlignmentX(Component.LEFT_ALIGNMENT);b.addActionListener(e->app.advanced.select(name));side.add(b);side.add(Box.createVerticalStrut(2));navigation.put(name,b);}}
    void updateSelection(){String selected=app.tools.getTitleAt(app.tools.getSelectedIndex());currentTool.setText(TITLES.getOrDefault(selected,selected));for(var entry:navigation.entrySet()){boolean on=entry.getKey().equals(selected);entry.getValue().setBackground(on?new Color(0x2A2A2A):VulnTheme.NAV);entry.getValue().setForeground(on?VulnTheme.TEXT:VulnTheme.MUTED);} }
    void refresh(){proxyState.setText(app.proxy.running()?"●  Proxy :"+app.port.getValue():"○  Proxy stopped");proxyState.setForeground(app.proxy.running()?VulnTheme.ACCENT:VulnTheme.MUTED);tlsState.setText(app.proxy.mitm?"TLS inspection on":"TLS tunnel");messageCount.setText(app.entries.size()+" messages");overview.refresh();}
    void bindings(){JRootPane root=app.getRootPane();bind(root,"F1","wiki",app::showWiki);bind(root,"control K","palette",this::palette);bind(root,"control shift S","save-project",app.advanced::saveProject);bind(root,"control O","open-project",app.advanced::openProject);bind(root,"control ENTER","send",()->{app.tools.setSelectedIndex(3);if(app.send.isEnabled())app.sendRepeater();});}
    static void bind(JRootPane root,String key,String name,Runnable action){root.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW).put(KeyStroke.getKeyStroke(key),name);root.getActionMap().put(name,new AbstractAction(){public void actionPerformed(ActionEvent e){action.run();}});}
    void palette(){String[] choices=new String[app.tools.getTabCount()];for(int i=0;i<choices.length;i++)choices[i]=app.tools.getTitleAt(i);Object selected=JOptionPane.showInputDialog(app,"Choose a workspace tool","VULN · Switch tool",JOptionPane.PLAIN_MESSAGE,null,choices,choices[app.tools.getSelectedIndex()]);if(selected!=null)app.advanced.select(selected.toString());}
    final class Overview extends JPanel {
        final JLabel messages=metricValue(),hosts=metricValue(),findings=metricValue(),pending=metricValue();final DefaultTableModel recent=VulnApp.model("Method","Target / path","Status","Time");final LatencyChart chart=new LatencyChart();
        Overview(){super(new BorderLayout());setBackground(VulnTheme.CANVAS);JPanel content=new JPanel();content.setLayout(new BoxLayout(content,BoxLayout.Y_AXIS));content.setBorder(new EmptyBorder(26,26,24,26));content.setBackground(VulnTheme.CANVAS);
            JPanel heading=new JPanel(new BorderLayout());heading.setOpaque(false);JPanel text=new JPanel(new GridLayout(2,1,0,5));text.setOpaque(false);text.add(VulnTheme.label("Your traffic. In focus.",28,VulnTheme.TEXT));text.add(VulnTheme.label("Inspect, replay and audit HTTP traffic in one desktop workspace.",13,VulnTheme.MUTED));heading.add(text);JLabel session=VulnTheme.label("●  LOCAL SESSION",11,VulnTheme.ACCENT);heading.add(session,BorderLayout.EAST);heading.setMaximumSize(new Dimension(3000,70));content.add(heading);content.add(Box.createVerticalStrut(24));
            JPanel metrics=new JPanel(new GridLayout(1,4,12,0));metrics.setOpaque(false);metrics.add(metric("MESSAGES",messages,"Captured across all tools"));metrics.add(metric("TARGETS",hosts,"Observed hosts"));metrics.add(metric("FINDINGS",findings,"Evidence to review"));metrics.add(metric("INTERCEPT QUEUE",pending,"Messages awaiting a decision"));metrics.setMaximumSize(new Dimension(3000,116));content.add(metrics);content.add(Box.createVerticalStrut(20));
            JPanel middle=new JPanel(new GridLayout(1,2,16,0));middle.setOpaque(false);VulnTheme.Card activity=new VulnTheme.Card(new BorderLayout(0,12));activity.add(VulnTheme.label("Response latency",15,VulnTheme.TEXT),BorderLayout.NORTH);activity.add(chart);activity.add(VulnTheme.label("Actual captured requests · last 60 measurements",11,VulnTheme.MUTED),BorderLayout.SOUTH);middle.add(activity);VulnTheme.Card quick=new VulnTheme.Card(new BorderLayout(0,12));quick.add(VulnTheme.label("Start an investigation",15,VulnTheme.TEXT),BorderLayout.NORTH);JPanel links=new JPanel(new GridLayout(2,2,10,10));links.setOpaque(false);links.add(action("Intercept traffic","Proxy"));links.add(action("Replay a request","Repeater"));links.add(action("Audit a target","Scanner"));links.add(action("Run payloads","Intruder"));quick.add(links);quick.add(VulnApp.button("Start local test server",app::startDemo),BorderLayout.SOUTH);middle.add(quick);middle.setPreferredSize(new Dimension(1000,220));middle.setMaximumSize(new Dimension(3000,220));content.add(middle);content.add(Box.createVerticalStrut(20));
            VulnTheme.Card traffic=new VulnTheme.Card(new BorderLayout(0,12));JPanel title=new JPanel(new BorderLayout());title.setOpaque(false);title.add(VulnTheme.label("Recent traffic",15,VulnTheme.TEXT));JButton open=VulnApp.button("Open full history →",()->{app.advanced.select("Proxy");findHistory(app.tools.getComponentAt(2));});title.add(open,BorderLayout.EAST);traffic.add(title,BorderLayout.NORTH);JTable rows=new JTable(recent);rows.setRowHeight(30);rows.setFillsViewportHeight(true);JScrollPane list=new JScrollPane(rows);list.setBorder(null);traffic.add(list);traffic.setPreferredSize(new Dimension(900,240));traffic.setMaximumSize(new Dimension(3000,280));content.add(traffic);
            JScrollPane scroll=new JScrollPane(content);scroll.setBorder(null);scroll.getVerticalScrollBar().setUnitIncrement(20);add(scroll);app.historyModel.addTableModelListener(e->refreshRows());
        }
        void findHistory(Component c){if(c instanceof JTabbedPane pane&&pane.getTabCount()>1){pane.setSelectedIndex(1);return;}if(c instanceof Container container)for(Component child:container.getComponents())findHistory(child);}
        JLabel metricValue(){return VulnTheme.label("0",30,VulnTheme.TEXT);}
        VulnTheme.Card metric(String name,JLabel value,String subtitle){VulnTheme.Card c=new VulnTheme.Card(new BorderLayout(0,6));c.add(VulnTheme.label(name,10,VulnTheme.MUTED),BorderLayout.NORTH);c.add(value);c.add(VulnTheme.label(subtitle,10,VulnTheme.MUTED),BorderLayout.SOUTH);return c;}
        JButton action(String title,String tool){JButton b=VulnApp.button(title+"  ↗",()->app.advanced.select(tool));b.setHorizontalAlignment(SwingConstants.LEFT);return b;}
        void refresh(){messages.setText(String.valueOf(app.entries.size()));hosts.setText(String.valueOf(app.entries.stream().map(e->URI.create(e.url()).getHost()).distinct().count()));findings.setText(String.valueOf(app.advanced.findings.size()));pending.setText(String.valueOf(app.pending.size()+(app.current==null?0:1)));chart.repaint();}
        void refreshRows(){recent.setRowCount(0);for(int i=app.entries.size()-1;i>=Math.max(0,app.entries.size()-6);i--){var e=app.entries.get(i);URI uri=URI.create(e.url());recent.addRow(new Object[]{e.method(),uri.getAuthority()+uri.getRawPath()+(uri.getRawQuery()==null?"":"?"+uri.getRawQuery()),e.code(),e.millis()+" ms"});}}
        final class LatencyChart extends JPanel {
            LatencyChart(){setOpaque(false);setPreferredSize(new Dimension(300,100));}
            protected void paintComponent(Graphics graphics){super.paintComponent(graphics);Graphics2D g=(Graphics2D)graphics.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);int w=getWidth(),h=getHeight();g.setColor(VulnTheme.BORDER);for(int i=1;i<4;i++)g.drawLine(0,h*i/4,w,h*i/4);if(app.entries.isEmpty()){g.setFont(new Font("Segoe UI",Font.PLAIN,12));g.setColor(VulnTheme.MUTED);g.drawString("No traffic yet. Capture a request to begin.",12,h/2);g.dispose();return;}List<VulnApp.Exchange> points=app.entries.subList(Math.max(0,app.entries.size()-60),app.entries.size());long max=Math.max(1,points.stream().mapToLong(VulnApp.Exchange::millis).max().orElse(1));g.setColor(VulnTheme.ACCENT);g.setStroke(new BasicStroke(2f));int lastX=8,lastY=h-12;for(int i=0;i<points.size();i++){int x=8+(w-20)*i/Math.max(1,points.size()-1),y=h-12-(int)((h-28)*points.get(i).millis()/max);if(i>0)g.drawLine(lastX,lastY,x,y);g.fillOval(x-2,y-2,4,4);lastX=x;lastY=y;}g.setFont(new Font("Segoe UI",Font.PLAIN,10));g.setColor(VulnTheme.MUTED);g.drawString(max+" ms",4,12);g.dispose();}
        }
    }
}
